// Package mod describes the JSON records accepted on standard input.
package mod

import "time"

type Module struct {
	Path      string
	Version   string
	Versions  []string
	Replace   *Module
	Time      *time.Time
	Update    *Module
	Main      bool
	Indirect  bool
	Dir       string
	GoMod     string
	GoVersion string
	Error     *ModuleError
}

type ModuleError struct {
	Err string
}

// Effective returns the one-level replacement, if there is one. The path and
// directness of a dependency still belong to the original module record.
func (m *Module) Effective() *Module {
	if m.Replace != nil {
		return m.Replace
	}
	return m
}

func (m *Module) ValidTimestamps() bool {
	m = m.Effective()
	if m.Time == nil || m.Update == nil {
		return true
	}
	return !m.Time.After(*m.Update.Time)
}
EOF
cat > main.go <<'EOF'
package main

import (
	"encoding/json"
	"flag"
	"io"
	"log"
	"os"
	"strconv"

	"local/outdated/internal/mod"
	"local/outdated/internal/table"
)

func main() {
	ci := flag.Bool("ci", false, "Non-zero exit code when at least one outdated dependency was found")
	direct := flag.Bool("direct", false, "List only direct modules")
	style := flag.String("style", "default", "Output style, pass 'markdown' for a Markdown table")
	update := flag.Bool("update", false, "List only modules with updates")
	flag.Parse()

	code, err := run(os.Stdin, os.Stdout, *direct, *update, *ci, *style)
	if err != nil {
		log.Print(err)
		return
	}
	if code != 0 {
		os.Exit(code)
	}
}

func run(in io.Reader, out io.Writer, direct, update, ci bool, style string) (int, error) {
	decoder := json.NewDecoder(in)
	var modules []*mod.Module
	for {
		m := new(mod.Module)
		if err := decoder.Decode(m); err != nil {
			if err == io.EOF {
				break
			}
			return 0, err
		}
		if m.Main || (direct && m.Indirect) || (update && m.Update == nil) {
			continue
		}
		modules = append(modules, m)
	}

	rows := make([][]string, 0, len(modules))
	hasUpdates := false
	for _, m := range modules {
		effective := m.Effective()
		newVersion := ""
		if effective.Update != nil {
			newVersion = effective.Update.Version
			hasUpdates = true
		}
		rows = append(rows, []string{
			m.Path, effective.Version, newVersion,
			strconv.FormatBool(!m.Indirect), strconv.FormatBool(m.ValidTimestamps()),
		})
	}
	if len(rows) > 0 {
		table.Render(out, rows, style == "markdown")
	}
	if ci && hasUpdates {
		return 1, nil
	}
	return 0, nil
}
EOF"}

