{"command":"cat > internal/table/table.go <<'EOF'
// Package table renders the five-column report without external dependencies.
package table

import (
	"io"
	"regexp"
	"strings"
)

var headings = []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}
var number = regexp.MustCompile(`^-?(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)(?:\.[0-9]+)?$`)

// splitCell preserves short explicit lines. If any line is too wide, all of the
// cell's lines are reflowed using spaces as word boundaries. An unbreakable
// word is permitted to grow the width beyond the usual thirty columns.
func splitCell(text string) ([]string, int) {
	lines := strings.Split(text, "\n")
	width := 0
	for _, line := range lines {
		if w := displayWidth(line); w > width {
			width = w
		}
	}
	if width <= 30 {
		return lines, width
	}

	words := strings.Split(strings.Join(lines, " "), " ")
	width = 30
	for _, word := range words {
		if w := displayWidth(word); w > width {
			width = w
		}
	}
	lines = nil
	line := words[0]
	lineWidth := displayWidth(line)
	for _, word := range words[1:] {
		w := displayWidth(word)
		if lineWidth+1+w > width {
			lines = append(lines, line)
			line = word
			lineWidth = w
		} else {
			line += " " + word
			lineWidth += 1 + w
		}
	}
	lines = append(lines, line)
	return lines, width
}

func Render(out io.Writer, rows [][]string, markdown bool) {
	widths := make([]int, len(headings))
	for i, h := range headings {
		widths[i] = displayWidth(h)
	}
	cells := make([][][]string, len(rows))
	for r, row := range rows {
		cells[r] = make([][]string, len(headings))
		for c, value := range row {
			lines, width := splitCell(value)
			cells[r][c] = lines
			if width > widths[c] {
				widths[c] = width
			}
		}
	}

	var b strings.Builder
	boundary := "+"
	if markdown {
		boundary = "|"
	}
	separator := func() {
		b.WriteString(boundary)
		for _, w := range widths {
			b.WriteString(strings.Repeat("-", w+2))
			b.WriteString(boundary)
		}
		b.WriteByte('\n')
	}
	if !markdown {
		separator()
	}
	b.WriteByte('|')
	for c, h := range headings {
		extra := widths[c] - displayWidth(h)
		b.WriteByte(' ')
		b.WriteString(strings.Repeat(" ", extra/2))
		b.WriteString(h)
		b.WriteString(strings.Repeat(" ", extra-extra/2))
		b.WriteString(" |")
	}
	b.WriteByte('\n')
	separator()
	for _, row := range cells {
		height := 1
		for _, cell := range row {
			if len(cell) > height {
				height = len(cell)
			}
		}
		for line := 0; line < height; line++ {
			b.WriteByte('|')
			for col, cell := range row {
				s := ""
				if line < len(cell) {
					s = cell[line]
				}
				extra := widths[col] - displayWidth(s)
				if extra < 0 {
					extra = 0
				}
				padding := strings.Repeat(" ", extra)
				b.WriteByte(' ')
				if number.MatchString(strings.TrimSpace(s)) {
					b.WriteString(padding)
					b.WriteString(s)
				} else {
					b.WriteString(s)
					b.WriteString(padding)
				}
				b.WriteString(" |")
			}
			b.WriteByte('\n')
		}
	}
	if !markdown {
		separator()
	}
	_, _ = io.WriteString(out, b.String())
}
EOF
cat > internal/table/width.go <<'EOF'
package table

import (
	"os"
	"regexp"
	"unicode"
)

// Only ANSI graphic rendition sequences are excluded from the measured text.
var rendition = regexp.MustCompile("\x1b\\[[0-9;]*m")
var eastAsian = os.Getenv("RUNEWIDTH_EASTASIAN") == "1"

type interval struct{ first, last rune }

func inIntervals(r rune, intervals []interval) bool {
	lo, hi := 0, len(intervals)
	for lo < hi {
		mid := (lo + hi) / 2
		v := intervals[mid]
		if r < v.first {
			hi = mid
		} else if r > v.last {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}

func runeWidth(r rune) int {
	if r < 0x20 || r >= 0x7f && r < 0xa0 || r == 0xad ||
		r == 0x70f || r == 0x180b || r == 0x180c || r == 0x180d || r == 0x180e ||
		r >= 0x200b && r <= 0x200f || r >= 0x2028 && r <= 0x202e ||
		r >= 0x2060 && r <= 0x2063 || r == 0xfeff || r >= 0xfff9 && r <= 0xfffb ||
		unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) {
		return 0
	}
	if inIntervals(r, wide) || eastAsian && inIntervals(r, ambiguous) {
		return 2
	}
	return 1
}

func isExtend(r rune) bool {
	return unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) ||
		unicode.Is(unicode.Mc, r) || r == 0x200c || r == 0x200d ||
		r >= 0x1f3fb && r <= 0x1f3ff || r >= 0xe0020 && r <= 0xe007f
}

func isRegional(r rune) bool { return r >= 0x1f1e6 && r <= 0x1f1ff }
func isPicture(r rune) bool {
	return r >= 0x1f000 && r <= 0x1faff || r >= 0x2600 && r <= 0x27bf ||
		r == 0x00a9 || r == 0x00ae || r == 0x203c || r == 0x2049 || r == 0x2122 || r == 0x2139 ||
		r >= 0x2194 && r <= 0x2199 || r == 0x21a9 || r == 0x21aa ||
		r == 0x231a || r == 0x231b || r == 0x2328 || r == 0x23cf ||
		r >= 0x23e9 && r <= 0x23f3 || r >= 0x23f8 && r <= 0x23fa ||
		r == 0x24c2 || r == 0x25aa || r == 0x25ab || r == 0x25b6 || r == 0x25c0 ||
		r >= 0x25fb && r <= 0x25fe || r == 0x2934 || r == 0x2935 ||
		r >= 0x2b05 && r <= 0x2b07 || r == 0x2b1b || r == 0x2b1c || r == 0x2b50 || r == 0x2b55 ||
		r == 0x3030 || r == 0x303d || r == 0x3297 || r == 0x3299
}

func hangulClass(r rune) int {
	switch {
	case r >= 0x1100 && r <= 0x115f || r >= 0xa960 && r <= 0xa97c:
		return 1 // L
	case r >= 0x1160 && r <= 0x11a7 || r >= 0xd7b0 && r <= 0xd7c6:
		return 2 // V
	case r >= 0x11a8 && r <= 0x11ff || r >= 0xd7cb && r <= 0xd7fb:
		return 3 // T
	case r >= 0xac00 && r <= 0xd7a3:
		if (r-0xac00)%28 == 0 {
			return 4 // LV
		}
		return 5 // LVT
	}
	return 0
}

func displayWidth(s string) int {
	s = rendition.ReplaceAllString(s, "")
	width, clusterWidth := 0, 0
	var prev rune
	regionalCount := 0
	pictureCluster, joinPicture := false, false
	first := true
	for _, r := range s {
		prevHangul, nextHangul := hangulClass(prev), hangulClass(r)
		connected := !first && (isExtend(r) ||
			joinPicture && isPicture(r) ||
			isRegional(prev) && isRegional(r) && regionalCount%2 == 1 ||
			prevHangul == 1 && (nextHangul == 1 || nextHangul == 2 || nextHangul == 4 || nextHangul == 5) ||
			(prevHangul == 2 || prevHangul == 4) && (nextHangul == 2 || nextHangul == 3) ||
			(prevHangul == 3 || prevHangul == 5) && nextHangul == 3)
		if !connected {
			width += clusterWidth
			clusterWidth = 0
			pictureCluster = false
			regionalCount = 0
		}
		if clusterWidth == 0 {
			clusterWidth = runeWidth(r)
		}
		if isRegional(r) {
			regionalCount++
		}
		if isPicture(r) {
			pictureCluster = true
		}
		joinPicture = r == 0x200d && pictureCluster
		prev = r
		first = false
	}
	return width + clusterWidth
}
EOF
