import unicodedata as u
# Generate self-contained Unicode width tables using Python's standard Unicode
# database. Later additions not supported by the observed formatter are omitted.
exclude=[(0x1fae0,0x1fae7),(0x1faf0,0x1faf6),(0x1f979,0x1f979),(0x1f6dd,0x1f6df),(0x1fa7b,0x1fa7c),(0x1faa9,0x1faac),(0x1fab7,0x1faba),(0x1fac3,0x1fac5)]
def ranges(pred):
 rs=[];start=None;prev=None
 for n in range(0x110000):
  if pred(n):
   if start is None:start=n
   prev=n
  elif start is not None:
   rs.append((start,prev));start=None
 if start is not None:rs.append((start,prev))
 return rs
with open('internal/table/unicode_width.go','w') as f:
 f.write('// Unicode character width intervals for terminal report formatting.\npackage table\n\n')
 for name,pred in [('wide',lambda n: u.category(chr(n))!='Cn' and u.east_asian_width(chr(n)) in ('W','F') and not any(a<=n<=b for a,b in exclude)),('ambiguous',lambda n:u.east_asian_width(chr(n))=='A')]:
  f.write('var '+name+' = []interval{\n')
  for a,b in ranges(pred):f.write('\t{0x%x, 0x%x},\n'%(a,b))
  f.write('}\n\n')
