cat > internal/table/locale.go <<'EOF'
package table

import (
	"os"
	"regexp"
	"strings"
)

var localeEncoding = regexp.MustCompile(`^[a-z]{2,3}(?:_[A-Z]{2})?\.(.+)$`)

func detectEastAsian() bool {
	if value := os.Getenv("RUNEWIDTH_EASTASIAN"); value != "" {
		return value == "1"
	}
	locale := os.Getenv("LC_ALL")
	if locale == "" {
		locale = os.Getenv("LC_CTYPE")
	}
	if locale == "" {
		locale = os.Getenv("LANG")
	}
	locale = strings.TrimSpace(locale)
	if modifier := strings.IndexByte(locale, '@'); modifier >= 0 {
		locale = locale[:modifier]
	}
	encoding := locale
	if match := localeEncoding.FindStringSubmatch(locale); match != nil {
		encoding = match[1]
	}
	encoding = strings.ToLower(encoding)
	if encoding == "utf8" || encoding == "utf-8" {
		return strings.HasPrefix(locale, "ja") || strings.HasPrefix(locale, "ko") || strings.HasPrefix(locale, "zh")
	}
	switch encoding {
	case "eucjp", "euckr", "sjis", "jis", "cp932", "cp51932", "cp936", "cp949", "cp950", "big5", "gb2312", "gbk":
		return true
	}
	return false
}
EOF
